contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 reqID, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        require(duration > 0, "duration must be positive");
        require(loanToCollateral > 0, "loanToCollateral must be positive");

        c.requestLoan(amount, interest, loanToCollateral, duration); if (__ESBMC_reverted()) return;
        bool activeBefore = c.isActive(reqID); if (__ESBMC_reverted()) return;
        c.rescindRequest(reqID); if (__ESBMC_reverted()) return;
        bool activeAfter = c.isActive(reqID); if (__ESBMC_reverted()) return;

        assert(activeBefore == true && activeAfter == false);
    }
}

