pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqID, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) internal {
        vm.assume(duration > 0);
        vm.assume(loanToCollateral > 0);
        try c.requestLoan(amount, interest, loanToCollateral, duration) {} catch { return; }
        bool activeBefore;
        try c.isActive(reqID) returns (bool __r) { activeBefore = __r; } catch { return; }
        try c.rescindRequest(reqID) {} catch { return; }
        bool activeAfter;
        try c.isActive(reqID) returns (bool __r) { activeAfter = __r; } catch { return; }
        assertTrue(activeBefore == true && activeAfter == false);
    }

    function testFuzz_run(uint256 reqID, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        _run(reqID, amount, interest, loanToCollateral, duration);
    }

    receive() external payable {}
}
